import React, { useState } from 'react';
import DashboardLayout from '../components/DashboardLayout';

const cropResults = [
  { name: 'Wheat', icon: '🌾', confidence: 94, profit: 42000, risk: 'Low', season: 'Rabi', water: 'Medium', days: 120, reason: 'Ideal for black cotton soil with current pH 6.8 and winter season.' },
  { name: 'Chickpea', icon: '🫘', confidence: 87, profit: 35000, risk: 'Low', season: 'Rabi', water: 'Low', days: 100, reason: 'Drought-tolerant, fixes nitrogen in soil. Good market demand.' },
  { name: 'Mustard', icon: '🌻', confidence: 79, profit: 28000, risk: 'Medium', season: 'Rabi', water: 'Low', days: 90, reason: 'Fast growing, good for crop rotation after rice.' },
];

const soilTypes = ['Black Cotton', 'Red Laterite', 'Alluvial', 'Sandy Loam', 'Clay', 'Loamy'];
const seasons = ['Kharif (Jun–Oct)', 'Rabi (Nov–Mar)', 'Zaid (Mar–Jun)'];

function ConfidenceBar({ value, color = 'green' }) {
  const colors = { green: 'from-green-600 to-green-400', yellow: 'from-yellow-600 to-yellow-400', red: 'from-red-600 to-red-400' };
  return (
    <div className="flex items-center gap-2">
      <div className="flex-1 h-2 bg-black/40 rounded-full overflow-hidden">
        <div className={`h-full bg-gradient-to-r ${colors[color]} rounded-full transition-all duration-1000`} style={{ width: `${value}%` }} />
      </div>
      <span className={`text-xs font-bold text-${color}-400 w-8`}>{value}%</span>
    </div>
  );
}

export default function RecommendationPage() {
  const [form, setForm] = useState({ soil: '', season: '', acres: '', ph: '', nitrogen: '', irrigation: 'drip' });
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [selected, setSelected] = useState(0);

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const analyze = (e) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => { setResults(cropResults); setLoading(false); }, 2000);
  };

  const crop = results?.[selected];

  return (
    <DashboardLayout title="Smart Crop Recommendation" subtitle="AI-powered crop & profit analysis for your farm">
      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
        {/* Input Form */}
        <div className="lg:col-span-2">
          <div className="glass rounded-2xl p-6 border border-green-900/30">
            <div className="flex items-center gap-2 mb-6">
              <span className="text-xl">🧪</span>
              <h3 className="font-display font-semibold text-white">Farm & Soil Details</h3>
            </div>
            <form onSubmit={analyze} className="space-y-4">
              <div>
                <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Soil Type</label>
                <select value={form.soil} onChange={e => set('soil', e.target.value)}
                  className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm">
                  <option value="">Select soil type</option>
                  {soilTypes.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div>
                <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Season</label>
                <select value={form.season} onChange={e => set('season', e.target.value)}
                  className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm">
                  <option value="">Select season</option>
                  {seasons.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Farm Size (Acres)</label>
                  <input value={form.acres} onChange={e => set('acres', e.target.value)} placeholder="e.g. 5" type="number"
                    className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm placeholder-gray-600" />
                </div>
                <div>
                  <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Soil pH</label>
                  <input value={form.ph} onChange={e => set('ph', e.target.value)} placeholder="e.g. 6.8" type="number" step="0.1"
                    className="w-full bg-black/30 border border-green-900/40 text-white rounded-xl px-3 py-3 text-sm placeholder-gray-600" />
                </div>
              </div>
              <div>
                <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Nitrogen Level</label>
                <div className="flex gap-2">
                  {['Low', 'Medium', 'High'].map(n => (
                    <button key={n} type="button" onClick={() => set('nitrogen', n)}
                      className={`flex-1 py-2 rounded-xl text-xs font-medium transition-all ${form.nitrogen === n ? 'btn-primary text-white' : 'glass-dark text-gray-400 hover:text-white'}`}>
                      {n}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <label className="text-gray-400 text-xs uppercase tracking-wider mb-1.5 block">Irrigation Type</label>
                <div className="flex gap-2">
                  {['drip', 'flood', 'rain-fed'].map(n => (
                    <button key={n} type="button" onClick={() => set('irrigation', n)}
                      className={`flex-1 py-2 rounded-xl text-xs font-medium transition-all capitalize ${form.irrigation === n ? 'btn-primary text-white' : 'glass-dark text-gray-400 hover:text-white'}`}>
                      {n}
                    </button>
                  ))}
                </div>
              </div>
              <button type="submit" disabled={loading}
                className={`w-full btn-primary text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 ${loading ? 'opacity-70' : ''}`}>
                {loading ? <><span className="animate-spin">⟳</span> AI Analyzing...</> : '🤖 Get AI Recommendations'}
              </button>
            </form>
          </div>
        </div>

        {/* Results */}
        <div className="lg:col-span-3 space-y-4">
          {!results ? (
            <div className="glass rounded-2xl p-12 border border-green-900/30 text-center">
              <div className="text-6xl mb-4 animate-float">🌱</div>
              <div className="text-white font-semibold text-lg mb-2">Ready to Analyze</div>
              <div className="text-gray-400 text-sm">Fill in your farm details and let AI recommend the best crops for maximum profit.</div>
            </div>
          ) : (
            <>
              {/* Crop Tabs */}
              <div className="flex gap-3">
                {results.map((r, i) => (
                  <button key={i} onClick={() => setSelected(i)}
                    className={`flex-1 glass rounded-xl p-3 text-center transition-all border ${selected === i ? 'border-green-500/50 bg-green-900/20' : 'border-green-900/30 hover:border-green-700/40'}`}>
                    <div className="text-2xl mb-1">{r.icon}</div>
                    <div className="text-white text-xs font-semibold">{r.name}</div>
                    <div className="text-green-400 text-xs">{r.confidence}%</div>
                  </button>
                ))}
              </div>

              {/* Selected Crop Detail */}
              {crop && (
                <div className="glass rounded-2xl p-6 border border-green-500/30 animate-fade-in">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <span className="text-5xl">{crop.icon}</span>
                      <div>
                        <h3 className="font-display font-bold text-2xl gradient-text">{crop.name}</h3>
                        <div className="text-gray-400 text-sm">{crop.season} · {crop.days} days</div>
                      </div>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-xs font-bold border ${crop.risk === 'Low' ? 'bg-green-500/20 text-green-400 border-green-500/30' : 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'}`}>
                      {crop.risk} Risk
                    </span>
                  </div>

                  <div className="glass-dark rounded-xl p-4 mb-4">
                    <div className="text-gray-400 text-xs mb-2">AI Confidence Score</div>
                    <ConfidenceBar value={crop.confidence} />
                  </div>

                  <div className="grid grid-cols-3 gap-3 mb-4">
                    <div className="glass-dark rounded-xl p-3 text-center">
                      <div className="text-green-400 font-bold text-lg">₹{(crop.profit / 1000).toFixed(0)}K</div>
                      <div className="text-gray-500 text-xs">Est. Profit</div>
                    </div>
                    <div className="glass-dark rounded-xl p-3 text-center">
                      <div className="text-blue-400 font-bold text-lg">{crop.water}</div>
                      <div className="text-gray-500 text-xs">Water Need</div>
                    </div>
                    <div className="glass-dark rounded-xl p-3 text-center">
                      <div className="text-yellow-400 font-bold text-lg">{crop.days}d</div>
                      <div className="text-gray-500 text-xs">Duration</div>
                    </div>
                  </div>

                  <div className="glass-green rounded-xl p-4">
                    <div className="text-green-300 text-xs font-semibold mb-1">🤖 AI Reasoning</div>
                    <div className="text-gray-300 text-sm">{crop.reason}</div>
                  </div>
                </div>
              )}

              {/* Profit Comparison */}
              <div className="glass rounded-2xl p-6 border border-green-900/30">
                <h4 className="font-semibold text-white mb-4">💰 Profit Comparison</h4>
                <div className="space-y-3">
                  {results.map((r, i) => (
                    <div key={i} className="flex items-center gap-3">
                      <span className="text-lg w-6">{r.icon}</span>
                      <span className="text-gray-300 text-sm w-20">{r.name}</span>
                      <div className="flex-1 h-2 bg-black/40 rounded-full overflow-hidden">
                        <div className="h-full bg-gradient-to-r from-green-700 to-green-400 rounded-full transition-all duration-1000"
                          style={{ width: `${(r.profit / 50000) * 100}%` }} />
                      </div>
                      <span className="text-green-400 text-sm font-semibold w-16 text-right">₹{(r.profit / 1000).toFixed(0)}K</span>
                    </div>
                  ))}
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </DashboardLayout>
  );
}
